div.script:
        document.getElementById("year").textContent =
          new Date().getFullYear();

        document.getElementById("homeTab").onclick = function () {
          document.getElementById("home").style.display = "block";
          document.getElementById("vouches").style.display = "none";
        };

        document.getElementById("vouchTab").onclick = function () {
          document.getElementById("home").style.display = "none";
          document.getElementById("vouches").style.display = "block";
        };

        const SUPABASE_URL = "https://jluzslhbqtjmvdzsdfhq.supabase.co";
        const SUPABASE_KEY = "sb_publishable_pJY2pUAWLJaD7sQ3Cq9UNA_BgmvNQT5";

        const status = document.getElementById("liveStatus");
        const list = document.getElementById("vouchList");
        const form = document.getElementById("vouchForm");
        const submitButton = document.getElementById("submitVouch");

        function showMessage(text) {
          list.replaceChildren();
          const p = document.createElement("p");
          p.textContent = text;
          list.appendChild(p);
        }

        if (
          !SUPABASE_URL.startsWith("YOUR_") &&
          !SUPABASE_KEY.startsWith("YOUR_") &&
          window.supabase
        ) {
          const db = window.supabase.createClient(
            SUPABASE_URL,
            SUPABASE_KEY
          );

          async function loadVouches() {
            const { data, error } = await db
              .from("vouches")
              .select("id,name,message,created_at")
              .order("created_at", { ascending: false })
              .limit(100);

            if (error) {
              status.textContent = "Unable to load vouches.";
              showMessage(error.message);
              return;
            }

            list.replaceChildren();
            document.getElementById("vouchCount").textContent =
              data.length;

            if (data.length === 0) {
              showMessage("No vouches yet.");
              return;
            }

            data.forEach(function (v) {
              const card = document.createElement("div");
              card.className = "vouch-card";

              const name = document.createElement("strong");
              name.textContent = v.name;

              const date = document.createElement("small");
              date.textContent =
                " · " + new Date(v.created_at).toLocaleString();

              const content = document.createElement("p");
              content.textContent = v.message;

              card.append(name, date, content);
              list.appendChild(card);
            });
          }

          loadVouches();

          db.channel("vouches-live")
            .on("postgres_changes", {
              event: "*",
              schema: "public",
              table: "vouches",
              filter: undefined
            }, function () {
              loadVouches();
            })
            .subscribe(function (state) {
              if (state === "SUBSCRIBED") {
                status.textContent = "● Live updates connected";
              } else if (state === "CHANNEL_ERROR") {
                status.textContent = "Live connection error.";
              } else {
                status.textContent = "Connecting to live updates...";
              }
            });

          form.addEventListener("submit", async function (event) {
            event.preventDefault();

            const name = document.getElementById("vouchName")
              .value.trim();
            const message = document.getElementById("vouchMessage")
              .value.trim();

            if (!name || !message) return;

            submitButton.disabled = true;
            status.textContent = "Submitting vouch...";

            const { error } = await db.from("vouches").insert({
              name: name,
              message: message
            });

            submitButton.disabled = false;

            if (error) {
              status.textContent = "Submission failed.";
              console.error(error);
              return;
            }

            form.reset();
            status.textContent = "Vouch submitted!";
            await loadVouches();
          });
        } else {
          status.textContent =
            "Configure your Supabase URL and publishable key.";
          showMessage("Live vouches require Supabase configuration.");
          submitButton.disabled = true;
        }
